//! Derived pendulum state from the pinned Village.update source acquisition.
//! Random initial motion phases are acquired once, never generated by this port.
use bevy::math::{DQuat, DVec3};
use serde::Deserialize;

/// Wind components use the source X/Z plane and metres per second.
#[derive(Clone, Copy, Debug, Deserialize)]
pub struct Wind {
    pub speed: f64,
    pub direction: [f64; 2],
}

#[derive(Clone, Copy, Debug, Deserialize)]
pub struct LanternMotion {
    pub t: f64,
    pub ph: f64,
    pub x: f64,
    pub z: f64,
    pub vx: f64,
    pub vz: f64,
}

#[derive(Clone, Copy, Debug, Deserialize)]
pub struct SignMotion {
    pub t: f64,
    pub a: f64,
    pub av: f64,
    pub b: f64,
    pub bv: f64,
}

impl Wind {
    fn validate(self) -> Result<(), String> {
        let [x, z] = self.direction;
        if !self.speed.is_finite()
            || self.speed < 0.0
            || !x.is_finite()
            || !z.is_finite()
            || (x.hypot(z) - 1.0).abs() > 1e-12
        {
            return Err("Pier motion requires finite source wind and a unit direction".into());
        }
        Ok(())
    }
}

fn steps(dt: f64, wind: Wind) -> Result<(usize, f64), String> {
    wind.validate()?;
    if !dt.is_finite() || dt < 0.0 {
        return Err("Pier motion delta must be finite and nonnegative".into());
    }
    let bounded = dt.min(0.1);
    #[allow(
        clippy::cast_possible_truncation,
        clippy::cast_sign_loss,
        reason = "The source clamps delta to 0.1 seconds, so this integral count is in 1..=12."
    )]
    let n = (bounded / (1.0 / 120.0)).ceil().max(1.0) as usize;
    #[allow(
        clippy::cast_precision_loss,
        reason = "The bounded source substep count is at most twelve."
    )]
    Ok((n, bounded / n as f64))
}

impl LanternMotion {
    pub fn validate(self) -> Result<(), String> {
        if [self.t, self.ph, self.x, self.z, self.vx, self.vz]
            .iter()
            .any(|v| !v.is_finite())
        {
            return Err("Nonfinite acquired lantern motion state".into());
        }
        Ok(())
    }

    /// Advance the original semi-implicit pendulum with its original substeps.
    /// Invalid input preserves the previous state.
    pub fn advance(&mut self, dt: f64, wind: Wind) -> Result<(), String> {
        self.validate()?;
        let (n, h) = steps(dt, wind)?;
        let mut next = *self;
        let v = wind.speed;
        let [wx, wz] = wind.direction;
        let w = 5.4;
        let damping = 0.05;
        for _ in 0..n {
            next.t += h;
            let t = next.t;
            let p = next.ph;
            let gust = 1.0
                + 0.4 * (t * 0.73 + p).sin() * (t * 0.31 + p * 0.5).sin()
                + 0.25 * (t * 2.3 + (t * 0.9 + p).sin() * 1.5).sin();
            let px = 0.0011 * v * v * gust * wx
                + 0.0012 * v * (t * 1.9 + p + (t * 0.53).sin() * 2.0).sin();
            let pz = 0.0011 * v * v * gust * wz
                + 0.0012 * v * (t * 1.6 + p * 1.7 + (t * 0.41).sin() * 2.0).sin();
            next.vx += (w * w * (px - next.x) - 2.0 * damping * w * next.vx) * h;
            next.x += next.vx * h;
            next.vz += (w * w * (pz - next.z) - 2.0 * damping * w * next.vz) * h;
            next.z += next.vz * h;
        }
        next.validate()?;
        *self = next;
        Ok(())
    }

    #[must_use]
    pub fn rotation(self) -> DQuat {
        source_xyz(self.z, 0.0, -self.x)
    }

    #[must_use]
    pub fn centre(self, pivot: DVec3, rest: DVec3) -> DVec3 {
        self.rotation() * (rest - pivot) + pivot
    }
}

impl SignMotion {
    pub fn validate(self) -> Result<(), String> {
        if [self.t, self.a, self.av, self.b, self.bv]
            .iter()
            .any(|v| !v.is_finite())
        {
            return Err("Nonfinite acquired sign motion state".into());
        }
        Ok(())
    }

    pub fn advance(&mut self, dt: f64, wind: Wind) -> Result<(), String> {
        self.validate()?;
        let (n, h) = steps(dt, wind)?;
        let mut next = *self;
        let v = wind.speed;
        let [wx, wz] = wind.direction;
        let w = 4.9;
        let wt = 10.5;
        for _ in 0..n {
            next.t += h;
            let t = next.t;
            let gust = 1.0
                + 0.35 * (t * 0.73 + 1.3).sin() * (t * 0.31).sin()
                + 0.22 * (t * 2.1 + (t * 0.9).sin()).sin()
                + 0.1 * (t * 5.3 + 2.0).sin();
            let push = -0.0033 * v * v * gust * wz * wz.abs()
                - 0.0009 * v * (t * 1.7 + (t * 0.43).sin() * 2.0).sin();
            next.av +=
                (w * w * (push * next.a.cos() - next.a.sin()) - 2.0 * 0.07 * w * next.av) * h;
            next.a += next.av * h;
            let twist = 0.004 * v * v * wx * wz * gust + 0.0015 * v * (t * 2.9 + 1.1).sin();
            next.bv += (wt * wt * (twist - next.b) - 2.0 * 0.12 * wt * next.bv) * h;
            next.b += next.bv * h;
        }
        next.validate()?;
        *self = next;
        Ok(())
    }

    #[must_use]
    pub fn rotation(self) -> DQuat {
        // Village constructs the sign with rotation.order = 'YXZ'.
        let (s1, c1) = (self.a / 2.0).sin_cos();
        let (s2, c2) = (self.b / 2.0).sin_cos();
        DQuat::from_xyzw(s1 * c2, c1 * s2, -s1 * s2, c1 * c2)
    }
}

// Preserve the acquired engine's Quaternion.setFromEuler('XYZ') convention
// explicitly; cached math-library Euler conventions must not alter the source.
fn source_xyz(x: f64, y: f64, z: f64) -> DQuat {
    let (s1, c1) = (x / 2.0).sin_cos();
    let (s2, c2) = (y / 2.0).sin_cos();
    let (s3, c3) = (z / 2.0).sin_cos();
    DQuat::from_xyzw(
        s1 * c2 * c3 + c1 * s2 * s3,
        c1 * s2 * c3 - s1 * c2 * s3,
        c1 * c2 * s3 + s1 * s2 * c3,
        c1 * c2 * c3 - s1 * s2 * s3,
    )
}
